document.addEventListener('DOMContentLoaded',()=>{const btn=document.getElementById('see-number-btn');if(btn)btn.addEventListener('click',validerEtVoirPro);});async function validerEtVoirPro(){const phoneEl=document.getElementById('client-phone');const errorEl=document.getElementById('error-msg');const inputZone=document.getElementById('input-zone');const resultZone=document.getElementById('result-zone');const proNumEl=document.getElementById('pro-num');const callLink=document.getElementById('call-link');const btn=document.getElementById('see-number-btn');if(!phoneEl || !btn || !errorEl)return;errorEl.style.display='none';errorEl.textContent='';const raw=phoneEl.value || '';const phone=raw.trim();if(!phone){showError('Saisissez votre numéro.');return;}const normalized=phone.replace(/[^0-9]/g,'');if(normalized.length<9 || normalized.length>15){showError('Numéro invalide.');return;}btn.disabled=true;const prevText=btn.innerText;btn.innerText='Chargement...';try{const sessionRes=await fetch('/get-session-commande');if(!sessionRes.ok)throw new Error('session-failed');const session=await sessionRes.json();const missionId=session.missionId;const prestaId=session.prestataireId;await fetch('/api/update-mission-phone',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({missionId,telephone:normalized})}).catch(()=>{});const res=await fetch('/get-prestataire-contact/'+encodeURIComponent(prestaId));if(!res.ok){showError("Le prestataire ne souhaite pas divulguer son numéro.");return;}const data=await res.json();const prestaPhone=(data && data.telephone)? data.telephone:null;if(!prestaPhone){showError('Numéro indisponible.');return;}proNumEl.textContent=prestaPhone;const phoneUrl='tel:'+prestaPhone.replace(/\s+/g,'');callLink.href=phoneUrl;if(inputZone)inputZone.style.display='none';if(resultZone)resultZone.style.display='block';setTimeout(()=>{window.location.href=phoneUrl;},200);}catch(err){showError('Erreur réseau. Réessayez.');}finally{btn.disabled=false;btn.innerText=prevText;}function showError(msg){errorEl.textContent=msg;errorEl.style.display='block';}}